// Desktop 2.0 snapshot: src/main/lyrics.ts. Generated by scripts/import-pc-2.mjs; platform adaptations are explicit in that script.
// Тексты песен (версия 1.6). Источники по приоритету:
//   1) YouTube Music: текст записи по videoId (как ytmusicapi get_watch_playlist -> get_lyrics):
//      синхронный (со временем строк) через мобильный клиент ANDROID_MUSIC, иначе обычный. Без входа в аккаунт.
//   2) LRCLIB (lrclib.net, бесплатно, без ключа): /api/get с названием, артистом, альбомом и длительностью,
//      затем /api/search; syncedLyrics (LRC), plainLyrics, instrumental.
//   3) Обычный текст из любого из них (без подсветки).
// Песни SoundCloud: та же песня ищется в YouTube Music (сопоставление по названию, артисту, длительности), затем LRCLIB.
// Кэш: файл на песню в %APPDATA%\music-circle-v2\lyrics (тексты не меняются), «текста нет» помним 3 дня.
// Ручной сдвиг человека для песни хранится отдельно (offsets.json) и не теряется при обновлении кэша.
import { existsSync, mkdirSync, readFileSync, renameSync, writeFileSync } from 'node:fs';
import path from 'node:path';
import { lyricsKey, parseLrc, type LyricLine, type LyricsResult } from '../shared/lyrics.js';
import { match, wantedFromCandidate } from './resolver/match.js';
import { findAll, ytmCall } from './resolver/providers/innertube.js';
import type { Candidate, FetchFn, SearchProvider } from './resolver/types.js';

/** Сколько помнить «текста нет» (вдруг появится). */
const NONE_TTL_MS = 3 * 24 * 60 * 60_000;
/** Допуск длительности текста LRCLIB к нашей версии песни при выборе (с). */
const LRCLIB_PICK_TOLERANCE_S = 2;
const ANDROID = { clientName: 'ANDROID_MUSIC', clientVersion: '7.21.50', androidSdkVersion: 34, hl: 'en' };

/** Текст без ручного сдвига (так он хранится в кэше). */
type Fetched = DistributiveOmit<LyricsResult, 'offsetMs'>;
type DistributiveOmit<T, K extends keyof T> = T extends unknown ? Omit<T, K> : never;

interface CacheEntry {
  at: number;
  result: Fetched;
}

interface LrclibItem {
  duration: number;
  syncedLyrics: string | null;
  plainLyrics: string | null;
  instrumental: boolean;
}

export interface LyricsOptions {
  dir: string;
  fetchFn: FetchFn;
  /** Поиск YouTube Music (для песен SoundCloud). */
  ytSearch: SearchProvider;
  version: string;
  log?: (m: string) => void;
  offsetRead?: (c:{source:string;id:string})=>number|null;
  offsetWrite?: (c:{source:string;id:string},ms:number)=>boolean;
}

export class Lyrics {
  private inFlight = new Map<string, Promise<Fetched>>();
  private offsets: Record<string, number> = {};
  private ua: string;

  constructor(private o: LyricsOptions) {
    mkdirSync(o.dir, { recursive: true });
    this.ua = `mwave/${o.version} (music player for Windows)`;
    try {
      this.offsets = JSON.parse(readFileSync(path.join(o.dir, 'offsets.json'), 'utf8'));
    } catch {
      this.offsets = {};
    }
  }

  private file(key: string): string {
    return path.join(this.o.dir, `${key.replace(/[^\w-]/g, '_').slice(0, 120)}.json`);
  }

  private cached(key: string): Fetched | null {
    try {
      const e = JSON.parse(readFileSync(this.file(key), 'utf8')) as CacheEntry;
      if (e.result.kind === 'none' && Date.now() - e.at > NONE_TTL_MS) return null;
      return e.result;
    } catch {
      return null;
    }
  }

  private store(key: string, result: Fetched): void {
    const tmp = `${this.file(key)}.tmp`;
    writeFileSync(tmp, JSON.stringify({ at: Date.now(), result } satisfies CacheEntry));
    renameSync(tmp, this.file(key));
  }

  /** Есть ли текст в кэше (для работы без сети). */
  hasCached(c: Candidate): boolean {
    return existsSync(this.file(lyricsKey(c)));
  }

  /** Текст песни: из кэша или из источников. playDuration: длительность нашей версии (с), для выбора текста LRCLIB. */
  async get(c: Candidate, playDuration: number | null, online = true): Promise<LyricsResult> {
    const key = lyricsKey(c);
    const offsetMs = this.offsets[key] ?? 0;
    const hit = this.cached(key);
    if (hit) return { ...hit, offsetMs } as LyricsResult;
    if (!online) return { kind: 'none', offsetMs };
    let p = this.inFlight.get(key);
    if (!p) {
      p = this.fetchAll(c, playDuration ?? c.duration)
        .then((r) => {
          this.store(key, r);
          return r;
        })
        .finally(() => this.inFlight.delete(key));
      this.inFlight.set(key, p);
    }
    try {
      return { ...(await p), offsetMs } as LyricsResult;
    } catch (e) {
      this.o.log?.(`[lyrics] «${c.title}»: ${(e as Error).message}`);
      return { kind: 'none', offsetMs };
    }
  }

  /** Запомненный сдвиг текста песни, мс. */
  offsetFor(c: { source: string; id: string }): number {
    return this.o.offsetRead?.(c) ?? this.offsets[lyricsKey(c)] ?? 0;
  }

  /** Сдвиг текста для песни (мс), запоминается. */
  setOffset(c: { source: string; id: string }, ms: number): void {
    const key = lyricsKey(c);
    const v = Math.max(-30_000, Math.min(30_000, Math.round(Number(ms) || 0)));
    if(this.o.offsetWrite?.(c,v))return;
    if (v) this.offsets[key] = v;
    else delete this.offsets[key];
    writeFileSync(path.join(this.o.dir, 'offsets.json'), JSON.stringify(this.offsets));
  }

  private async fetchAll(c: Candidate, duration: number | null): Promise<Fetched> {
    // 1) YouTube Music: для SoundCloud сначала та же песня в YouTube Music
    let videoId: string | null = c.source === 'ytmusic' ? c.id : null;
    let ytDuration: number | null = null;
    if (!videoId) {
      const wanted = wantedFromCandidate(c);
      const found = await this.o.ytSearch.search(`${wanted.artist} ${wanted.title}`, 5).catch(() => [] as Candidate[]);
      const m = match(found, { ...wanted, duration });
      videoId = m?.candidate.id ?? null;
      ytDuration = m?.candidate.duration ?? null;
    }
    let ytPlain: string | null = null;
    if (videoId) {
      const y = await this.fromYtm(videoId).catch(() => null);
      // Синхронный текст YouTube Music относится к той же записи; для песни SoundCloud сверяем длительность найденной записи
      if (y?.lines) return { kind: 'synced', lines: y.lines, source: 'YouTube Music', srcDuration: ytDuration };
      ytPlain = y?.plain ?? null;
    }
    // 2) LRCLIB
    const l = await this.fromLrclib(c, duration).catch(() => null);
    if (l?.instrumental) return { kind: 'instrumental', source: 'LRCLIB' };
    if (l?.syncedLyrics) {
      const lines = parseLrc(l.syncedLyrics);
      if (lines.length) return { kind: 'synced', lines, source: 'LRCLIB', srcDuration: l.duration || null };
    }
    // 3) Обычный текст
    if (ytPlain) return { kind: 'plain', text: ytPlain, source: 'YouTube Music' };
    if (l?.plainLyrics) return { kind: 'plain', text: l.plainLyrics, source: 'LRCLIB' };
    return { kind: 'none' };
  }

  /** YouTube Music: browseId текста из «next», затем текст мобильным клиентом (там есть время строк). */
  private async fromYtm(videoId: string): Promise<{ lines?: LyricLine[]; plain?: string } | null> {
    const next = await ytmCall(this.o.fetchFn, 'next', { videoId });
    const id = findAll<{ browseId?: string }>(next, 'browseEndpoint')
      .map((b) => b.browseId)
      .find((x) => x?.startsWith('MPLY'));
    if (!id) return null;
    const res = await this.o.fetchFn('https://music.youtube.com/youtubei/v1/browse?alt=json&prettyPrint=false', {
      method: 'POST',
      headers: { 'content-type': 'application/json', 'user-agent': 'com.google.android.apps.youtube.music/7.21.50 (Linux; U; Android 14) gzip' },
      body: JSON.stringify({ context: { client: ANDROID }, browseId: id }),
    });
    if (!res.ok) throw new Error(`YouTube Music: HTTP ${res.status}`);
    const data = await res.json();
    const timed = findAll<{ lyricLine?: string; cueRange?: { startTimeMilliseconds?: string } }[]>(data, 'timedLyricsData')[0] ?? [];
    if (timed.length && timed.every((l) => l.cueRange?.startTimeMilliseconds !== undefined)) {
      return { lines: timed.map((l) => ({ t: Number(l.cueRange!.startTimeMilliseconds), text: (l.lyricLine ?? '').trim() })).sort((a, b) => a.t - b.t) };
    }
    if (timed.length) return { plain: timed.map((l) => l.lyricLine ?? '').join('\n') };
    // Обычный текст (веб-клиент)
    const web = await ytmCall(this.o.fetchFn, 'browse', { browseId: id });
    const shelf = findAll<{ description?: { runs?: { text: string }[] } }>(web, 'musicDescriptionShelfRenderer')[0];
    const text = shelf?.description?.runs?.map((r) => r.text).join('') ?? '';
    return text.trim() ? { plain: text.replace(/\r\n/g, '\n') } : null;
  }

  /** LRCLIB: точный запрос, затем поиск; из найденного ближайший по длительности (синхронный в приоритете). */
  private async fromLrclib(c: Candidate, duration: number | null): Promise<LrclibItem | null> {
    const w = wantedFromCandidate(c);
    const headers = { 'user-agent': this.ua };
    const q = new URLSearchParams({ track_name: w.title, artist_name: w.artist });
    if (duration) q.set('duration', String(Math.round(duration)));
    const r = await this.o.fetchFn(`https://lrclib.net/api/get?${q}`, { headers });
    if (r.ok) return (await r.json()) as LrclibItem;
    const s = await this.o.fetchFn(`https://lrclib.net/api/search?${new URLSearchParams({ track_name: w.title, artist_name: w.artist })}`, { headers });
    if (!s.ok) return null;
    const list = ((await s.json()) as LrclibItem[]).filter((x) => !duration || !x.duration || Math.abs(x.duration - duration) <= LRCLIB_PICK_TOLERANCE_S + 1);
    return (
      list.sort(
        (a, b) => Number(!!b.syncedLyrics) - Number(!!a.syncedLyrics) || Math.abs(a.duration - (duration ?? a.duration)) - Math.abs(b.duration - (duration ?? b.duration)),
      )[0] ?? null
    );
  }
}
